// spec: specs/delivery.md §10 · кейс .qa/tests/delivery/dlv-14-rejected-delivery-note.md
// seed: tests/seed.admin.spec.ts
// #89b5f0 (עבר QA 26.10): /delivery/<id> ОТКЛОНЁННОГО заказа — у заголовка тег «נדחתה» (не «ממתינה להכנה»),
// нет панели «שיוך נהג ומסלול» (נהג / מסלול חלוקה / תאריך אספקה / שעת יעד / «שייך ושלח לנהג») и нет «ההזמנה טרם אושרה».
// Регресс: у ожидающего — «ההזמנה טרם אושרה» и неактивная панель (#6a7491c7); у утверждённого — панель на месте (#a8bdcb).
// Только чтение: заказы берутся динамически из /orders (вкладка «נדחו», фильтр «שלב ההזמנה»), id — из адреса карточки; ничего не сохраняется.
import { test, expect, Page } from '@playwright/test';

import * as path from 'path';

test.use({ storageState: path.resolve(__dirname, '../../../auth/admin.json') });

const rows = (page: Page) => page.getByRole('button', { name: /^#\d+ / });

async function openOrdersAll(page: Page) {
  await page.goto('/orders');
  await expect(page.getByRole('heading', { level: 1, name: 'הזמנות' })).toBeVisible({ timeout: 30_000 });
  await page.getByRole('combobox', { name: 'סינון לפי חודש' }).selectOption({ label: 'כל החודשים' });
  await expect(rows(page).first()).toBeVisible({ timeout: 30_000 });
}

/** Открывает i-ю строку списка, возвращает { id, no } из адреса и заголовка карточки. */
async function takeOrder(page: Page, i: number): Promise<{ id: string; no: string }> {
  const row = rows(page).nth(i);
  const no = ((await row.getAttribute('aria-label')) ?? (await row.innerText())).match(/#(\d+)/)![1];
  await row.click();
  await expect(page).toHaveURL(/\/orders\/[0-9a-f-]{36}$/, { timeout: 30_000 });
  await expect(page.getByRole('heading', { level: 1, name: new RegExp(`^הזמנה #${no}`) })).toBeVisible({ timeout: 30_000 });
  return { id: page.url().split('/').pop()!, no };
}

/** i-й отклонённый заказ (вкладка «נדחו»), или null. */
async function rejectedOrder(page: Page, i: number) {
  await openOrdersAll(page);
  await page.getByRole('button', { name: /^נדחו \d+$/ }).click();
  await expect(rows(page).first().or(page.getByText(/אין הזמנות|לא נמצאו הזמנות/).first())).toBeVisible({ timeout: 20_000 });
  if ((await rows(page).count()) <= i) return null;
  return takeOrder(page, i);
}

/** Первый заказ с этапом stage (фильтр «שלב ההזמנה»), или null. */
async function orderByStage(page: Page, stage: string) {
  await openOrdersAll(page);
  await page.getByRole('button', { name: 'סינון' }).click();
  await page.getByRole('combobox', { name: 'שלב ההזמנה' }).selectOption({ label: stage });
  await expect(rows(page).first().or(page.getByText('לא נמצאו הזמנות התואמות לסינון'))).toBeVisible({ timeout: 20_000 });
  if (!(await rows(page).count())) return null;
  return takeOrder(page, 0);
}

async function openNote(page: Page, o: { id: string; no: string }) {
  await page.goto(`/delivery/${o.id}`);
  const h1 = page.getByRole('heading', { level: 1, name: `תעודת משלוח · הזמנה #${o.no}` });
  await expect(h1).toBeVisible({ timeout: 30_000 });
  return h1.locator('..');
}

/** Проверки #89b5f0 на /delivery/<id> отклонённого заказа. */
async function expectRejectedNote(page: Page, o: { id: string; no: string }) {
  const header = await openNote(page, o);
  const main = page.getByRole('main');
  // тег «נדחתה» у заголовка (источник: «מה רצוי» — «התג «נדחתה»»)
  await expect(header).toContainText('נדחתה', { timeout: 20_000 });
  await expect(main.getByText('ההזמנה נדחתה').first()).toBeVisible({ timeout: 20_000 });
  await expect(main.getByText('ממתינה להכנה')).toHaveCount(0);
  // нет панели назначения (источник: «מה רצוי» — «בלי פאנל שיוך נהג»)
  await expect(main.getByText('שיוך נהג ומסלול')).toHaveCount(0);
  await expect(main.getByRole('combobox')).toHaveCount(0);
  await expect(main.getByRole('textbox')).toHaveCount(0);
  await expect(main.getByRole('button', { name: 'שייך ושלח לנהג' })).toHaveCount(0);
  await expect(main.getByText(/עדיין אין נהגים פעילים/)).toHaveCount(0);
  // нет «ההזמנה טרם אושרה» (источник: «מה רצוי» — «ובלי «ההזמנה טרם אושרה»»)
  await expect(main.getByText('ההזמנה טרם אושרה')).toHaveCount(0);
}

test.describe('delivery — תעודת משלוח של הזמנה שנדחתה (#89b5f0)', () => {
  for (const i of [0, 1]) {
    test(`מפיץ: הזמנה שנדחתה #${i + 1} מהרשימה — תג «נדחתה», בלי פאנל שיוך ובלי «טרם אושרה» #89b5f0 @desktop @prod-safe`, async ({ page }) => {
      const o = await rejectedOrder(page, i);
      test.skip(!o, `нет ${i + 1}-го отклонённого заказа`);
      await expectRejectedNote(page, o!);
    });
  }

  test('מפיץ 390: תעודה של הזמנה שנדחתה — אותו מצב #89b5f0 @iphone @prod-safe', async ({ page }) => {
    await page.setViewportSize({ width: 390, height: 844 });
    const o = await rejectedOrder(page, 0);
    test.skip(!o, 'нет отклонённых заказов');
    await expectRejectedNote(page, o!);
    expect(await page.evaluate(() => document.documentElement.scrollWidth - window.innerWidth)).toBeLessThanOrEqual(1);
  });

  test('רגרסיה: הזמנה ממתינה לאישור — «ההזמנה טרם אושרה» והפאנל לא פעיל #89b5f0 #6a7491c7 @desktop @prod-safe', async ({ page }) => {
    const o = await orderByStage(page, 'ממתינה לאישור');
    test.skip(!o, 'нет заказов «ממתינה לאישור»');
    const header = await openNote(page, o!);
    const main = page.getByRole('main');
    await expect(main.getByText('ההזמנה טרם אושרה')).toBeVisible({ timeout: 20_000 });
    await expect(main.getByRole('combobox', { name: 'נהג' })).toBeDisabled();
    await expect(main.getByRole('button', { name: 'שייך ושלח לנהג' })).toBeDisabled();
    await expect(header).not.toContainText('נדחתה');
  });

  test('רגרסיה: הזמנה מאושרת — פאנל «שיוך נהג ומסלול» במקומו, בלי «נדחתה» ובלי «טרם אושרה» #89b5f0 #a8bdcb @desktop @prod-safe', async ({ page }) => {
    const o = await orderByStage(page, 'ממתינה לליקוט');
    test.skip(!o, 'нет заказов «ממתינה לליקוט»');
    const header = await openNote(page, o!);
    const main = page.getByRole('main');
    await expect(main.getByText('שיוך נהג ומסלול')).toBeVisible({ timeout: 20_000 });
    await expect(main.getByRole('combobox', { name: 'נהג' })).toBeVisible({ timeout: 20_000 });
    await expect(header).not.toContainText('נדחתה');
    await expect(main.getByText('ההזמנה טרם אושרה')).toHaveCount(0);
    await expect(main.getByText('ההזמנה נדחתה')).toHaveCount(0);
  });
});
